// Exact source mean/reader lineage only. No nearest point or world station.
inline eventio::Json consume_joint_source_trace_lineage_v1(const JointProblemBuilder&b,const eventio::Json&cfg,eventio::Json&components,const eventio::Json&source_report){
 if(!cfg.contains("actual_source_trace_lineage_v1"))return {{"consumed",false},{"source_mean_trace_components_rebound",0}};
 const auto&ref=cfg.at("actual_source_trace_lineage_v1");auto file=ref.at("file").get<std::string>();eventio::verify(file,ref.at("sha256"));auto m=eventio::read_json(file);
 const auto verify=[](const eventio::Json&r){auto path=r.contains("file")?r.at("file").get<std::string>():r.at("path").get<std::string>();eventio::verify(path,r.at("sha256"));return path;};
 if(m.at("schema")!="rinkfit.selected_source_mean_trace_lineage.v1"||m.at("issuer").at("sha256")!="2faaa0c729c8b92714029f129143058ce94bb5ae11f8924c9a8a1de2bfcb1ec7")throw std::runtime_error("hybrid source trace lineage issuer/version mismatch");verify(m.at("issuer"));verify(m.at("source_packet"));if(m.at("source_packet").at("sha256")!=b.packet.source_hash)throw std::runtime_error("hybrid source trace lineage different exact current packet");
 for(const auto&r:m.at("actual_dependencies"))verify(r);
 if(m.at("actual_source_component_manifest").at("sha256")!=source_report.at("source_component_manifest").at("sha256"))throw std::runtime_error("hybrid source trace lineage different current component generation");
 auto feedback=eventio::read_json(verify(m.at("source_feedback")));if(feedback.at("actual_support_components").at("sha256")!=source_report.at("support_components").at("sha256"))throw std::runtime_error("hybrid trace lineage uses a different original support trace");
 std::map<std::string,eventio::Json>actual;std::ifstream in(verify(feedback.at("files").at("components")));std::string line;while(std::getline(in,line)){if(line.empty())continue;auto c=eventio::Json::parse(line);if(!actual.emplace(c.at("component_id").get<std::string>(),c).second)throw std::runtime_error("duplicate source feedback component");}
 std::map<std::size_t,const eventio::Json*>queries;for(const auto&q:b.packet.source_json.at("queries"))queries.emplace(q.at("row_index").get<std::size_t>(),&q);
 std::map<std::string,std::size_t>old;for(std::size_t k=0;k<components.size();++k)old.emplace(components[k].at("component_id").get<std::string>(),k);
 std::set<std::string>seen;std::size_t rows=0,exact=0,mapped=0,unknown=0,edges=0;
 for(const auto&c:m.at("components")){
  const auto id=c.at("component_id").get<std::string>();if(!seen.insert(id).second||!actual.count(id)||!old.count(id))throw std::runtime_error("lineage component absent/duplicate in actual source registry");auto&target=components.at(old.at(id));if(target.contains("source_Query_trace_mapping"))throw std::runtime_error("source lineage may not replace already mapped original components");
  const auto&trace=actual.at(id).at("actual_source_component_trace");if(trace.at("component_id")!=c.at("component_id")||!trace.at("edges_come_only_from_ordered_current_support_segments").get<bool>()||c.at("producer_ordered_raw_indices")!=trace.at("ordered_raw_indices"))throw std::runtime_error("source trace adjacency/producer raw sequence changed");
  if(c.at("world_or_model_coordinates_used").get<bool>()||c.at("nearest_or_array_ordinal_assignment_used").get<bool>()||!c.at("world_direction_is_not_measured").get<bool>()||c.at("allowed_world_direction_candidates")!=eventio::Json::array({1,-1}))throw std::runtime_error("source lineage illegally selected a world/order direction");
  std::set<std::size_t>selected;std::vector<std::pair<std::size_t,std::size_t>>ordered;eventio::Json mapping=eventio::Json::array();bool good=true;
  for(const auto&r:c.at("Query_rows")){
   ++rows;auto i=r.at("raw_index").get<std::size_t>();if(i>=b.packet.rows.size()||!selected.insert(i).second||!queries.count(i))throw std::runtime_error("source lineage Query raw partition invalid");const auto&o=b.packet.rows[i];const auto&q=*queries.at(i);if(!o.active||!o.query||r.at("original_Query")!=q||r.at("source_row_id")!=o.source_row_id||r.at("source_dataset_id")!=o.source_dataset_id||r.at("native_pts").get<std::int64_t>()!=o.pts||r.at("material_index").get<int>()!=o.material||q.at("source_component_id")!=c.at("component_id"))throw std::runtime_error("source lineage actual selected Query/ID/clock/material mismatch");
   const auto&mu=r.at("selected_source_UV");if(mu.size()!=2||mu[0].get<double>()!=o.uv[0]||mu[1].get<double>()!=o.uv[1])throw std::runtime_error("source lineage changed actual original two-dimensional UV");
   const auto&proof=r.at("finite_Query_selected_mean_proof");const auto&alpha=q.at("alpha");const auto&uv=q.at("native_uv");const auto&normal=proof.at("normal");std::size_t zero=alpha.size();for(std::size_t j=0;j<alpha.size();++j)if(alpha[j].get<double>()==0){if(zero!=alpha.size())throw std::runtime_error("lineage Query has multiple zero seeds");zero=j;}
   if(zero==alpha.size()||uv.size()!=alpha.size()||(alpha.size()!=25&&alpha.size()!=49)||normal.size()!=2||normal[0].get<double>()!=o.normal[0]||normal[1].get<double>()!=o.normal[1]||proof.at("source_seed_uv")!=uv[zero])throw std::runtime_error("lineage finite Query seed/normal/array mismatch");
   const double a=proof.at("selected_original_optical_alpha").get<double>();if(!std::isfinite(a)||a<alpha.front().get<double>()||a>alpha.back().get<double>())throw std::runtime_error("lineage actual selected source alpha outside original finite Query");
   for(int k=0;k<2;++k){const double seed=uv[zero][k].get<double>(),n=normal[k].get<double>();if(seed+a*n!=o.uv[k])throw std::runtime_error("lineage selected source mean lacks binary64 forward replay");for(std::size_t j=0;j<alpha.size();++j)if(seed+alpha[j].get<double>()*n!=uv[j][k].get<double>())throw std::runtime_error("lineage literal finite Query samples were changed");}
   std::vector<std::size_t>matches;for(std::size_t j=0;j<trace.at("current_uv").size();++j){const auto&v=trace.at("current_uv")[j];if(v[0].get<double>()==o.uv[0]&&v[1].get<double>()==o.uv[1])matches.push_back(j);}if(eventio::Json(matches)!=r.at("exact_current_trace_vertex_indices"))throw std::runtime_error("lineage exact current trace vertex proof changed");
   if(matches.size()==1){++exact;const auto j=matches.front();if(r.at("mapping_status")!="exact_unique_selected_source_mean_vertex"||r.at("ordered_trace_coordinate").get<std::size_t>()!=j||r.at("producer_raw_source_index")!=trace.at("ordered_raw_indices")[j])throw std::runtime_error("lineage selected trace vertex differs from real source index");ordered.emplace_back(j,i);mapping.push_back({{"row",i},{"ordered_trace_coordinate",j},{"source_only_exact_selected_mean_vertex_lineage",true},{"finite_Query_selected_original_alpha",a}});}else{good=false;if(r.at("mapping_status")!="unknown_current_trace_correspondence")throw std::runtime_error("unknown source relation was incorrectly issued as known");}
  }
  const auto expected=target.at("rows").get<std::vector<std::size_t>>();if(selected!=std::set<std::size_t>(expected.begin(),expected.end()))throw std::runtime_error("source lineage omitted selected Query from complete component");
  if(good){if(c.at("status")!="source_lineage_order_available")throw std::runtime_error("lineage full component status mismatch");std::sort(ordered.begin(),ordered.end());std::vector<std::size_t>rr;for(const auto&v:ordered){if(!rr.empty()&&v.first==ordered.at(rr.size()-1).first)throw std::runtime_error("source selected Queries share a trace vertex");rr.push_back(v.second);}if(eventio::Json(rr)!=c.at("ordered_selected_rows"))throw std::runtime_error("lineage source row order mismatch");target["previous_source_intersection_audit"]=target;target["rows"]=rr;target["source_Query_trace_mapping"]=mapping;target["source_trace_lineage_ref"]=ref;target["source_mapping_policy"]="exact unique selected native source mean vertex; complete original finite Query forward replay; no nearest/world/ordinal";++mapped;edges+=rr.size()-1;}
  else{++unknown;if(c.at("status")!="unknown_source_trace_mapping_retained"||target.contains("source_Query_trace_mapping"))throw std::runtime_error("unknown source component was silently mapped");}
 }
 if(seen.size()!=55||actual.size()!=55||rows!=166||exact!=119||mapped!=41||unknown!=14||edges!=78)throw std::runtime_error("lineage full55/166 source denominator changed");
 return {{"consumed",true},{"manifest",ref},{"actual_source_Query_rows",rows},{"exact_source_mean_vertex_rows",exact},{"source_mean_trace_components_rebound",mapped},{"unknown_components_retained",unknown},{"actual_source_edges_recovered",edges},{"Query_UV_W_or_finite_domain_modified",false},{"nearest_world_or_ordinal_mapping",false},{"physical_world_directions_selected",false}};
}
